"""Skill: restart the Mac."""

import re

from automation.system_control import restart_mac
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

_PATTERN = re.compile(
    r"(restart|reboot)\s*(the\s+)?(mac|macbook|computer|laptop|system)?$"
)


class RestartSystemSkill(Skill):
    name = "restart_system"
    description = "Restart the Mac (destructive!)"
    priority = 8

    def match(self, text: str) -> SkillMatch | None:
        low = text.lower().strip()
        if _PATTERN.search(low):
            return SkillMatch(confidence=0.95)
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        # Gated: irreversible. The gate lives in core/confirmation.py so
        # this skill cannot approve itself.
        async def _do() -> str:
            await run_in_thread(restart_mac)
            return "Restarting now."

        from core.confirmation import PendingAction
        return SkillResult(
            text="Restart your Mac? Say yes to confirm.",
            confirm=PendingAction(description="restart your Mac", run=_do),
        )
